KeyboardShortcuts component for displaying keyboard shortcut reference.
A modal dialog showing all available keyboard shortcuts organized by
category. Can be opened with Ctrl+/ or from the help menu.
@module components/help/KeyboardShortcuts
@example
```tsx
const [isOpen, setIsOpen] = useState(false);
// Open with keyboard shortcut
useEffect(() => {
const handler = (e: KeyboardEvent) => {
if (e.ctrlKey && e.key === '/') {
e.preventDefault();
setIsOpen(true);
}
};
window.addEventListener('keydown', handler);
return () => window.removeEventListener('keydown', handler);
}, []);
<KeyboardShortcuts isOpen={isOpen} onClose={() => setIsOpen(false)} />
```

OnboardingTour component for first-time user walkthrough.
Provides a step-by-step introduction to the UnaMentis web client,
highlighting key features and UI elements. The tour can be triggered
automatically for new users or manually from the help menu.
@module components/help/OnboardingTour
@example
```tsx
// Basic usage
<OnboardingTour isOpen={isFirstVisit} onClose={() => setIsFirstVisit(false)} />
// With completion callback
<OnboardingTour
isOpen={showTour}
onClose={() => setShowTour(false)}
onComplete={() => saveUserPreference('tour_completed', true)}
/>
```

Help system components for the UnaMentis web client.
This module provides a comprehensive help system including:
- Tooltips for contextual hints
- Help icons for inline documentation
- Onboarding tour for first-time users
- Help modal for full documentation
- Keyboard shortcuts reference
@module components/help
@example
```tsx
import {
Tooltip,
HelpIcon,
HelpModal,
KeyboardShortcuts,
OnboardingTour,
useOnboardingTour,
useKeyboardShortcuts,
} from '@/components/help';
function App() {
const [helpOpen, setHelpOpen] = useState(false);
const [shortcutsOpen, setShortcutsOpen] = useState(false);
const tour = useOnboardingTour();
useKeyboardShortcuts(
() => setShortcutsOpen(true),
() => setHelpOpen(true)
);
return (
<>
<HelpModal
isOpen={helpOpen}
onClose={() => setHelpOpen(false)}
onOpenKeyboardShortcuts={() => setShortcutsOpen(true)}
onStartTour={tour.openTour}
/>
<KeyboardShortcuts
isOpen={shortcutsOpen}
onClose={() => setShortcutsOpen(false)}
/>
<OnboardingTour
isOpen={tour.isOpen}
onClose={tour.closeTour}
onComplete={tour.completeTour}
/>
</>
);
}
```
